import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<{name:string, params:any, trigger:string}>} [cinematicPrimitives]
 * @property {any} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create a UI node for the thumbnail card.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;
  const root = new Group();

  // Store handlers and cleanup references
  root.userData.handlers = {};
  root.userData.cleanup = cleanup;

  // Load GLB mesh asynchronously and add to the group
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives if any
  const primitiveRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const ref = fn(root, prim.params);
        primitiveRefs.push(ref);
      }
    }
  }

  // --- Interaction: Hover lift (rise-in) ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: `+=${0.15}`,
    duration: 0.3,
    ease: 'power3.out',
  });

  // --- Interaction: Click press-down + emit ---
  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  });

  // Attach event handlers
  root.userData.handlers.hoverEnter = () => {
    hoverTimeline.play();
  };
  root.userData.handlers.hoverLeave = () => {
    hoverTimeline.reverse();
  };
  root.userData.handlers.click = () => {
    clickTimeline.play().then(() => {
      clickTimeline.reverse();
    });
    ctx.emit('hub-home.select', {});
  };

  // Cleanup function
  function cleanup() {
    // Kill GSAP timelines
    hoverTimeline.kill();
    clickTimeline.kill();

    // Dispose primitives
    for (const ref of primitiveRefs) {
      if (ref && typeof ref.cleanup === 'function') {
        ref.cleanup();
      }
    }

    // Dispose geometries and materials from GLB
    root.traverse((child) => {
      if (child instanceof Mesh) {
        if (child.geometry) child.geometry.dispose();
        if (Array.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m && m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  }

  return root;
}
